python3 - <<'PY'
p='src/types/checker/functions/resolution/signature.rs'
s=open(p).read()
old = """/// Returns whether one array element representation is wider than another.
fn element_representation_widens(entry: &PhpType, exit: &PhpType) -> bool {
    let entry = entry.codegen_repr();
    let exit = exit.codegen_repr();
    if entry == exit {
        return false;
    }
    entry == PhpType::Never || exit == PhpType::Mixed
}"""
new = """/// Returns whether one array element representation is wider than another.
///
/// `never` is compared on the RAW type, not on `codegen_repr()`: an empty array's element type
/// normalizes to `Void`, so asking `codegen_repr() == Never` is always false and the empty-array
/// case silently never fired.
fn element_representation_widens(entry: &PhpType, exit: &PhpType) -> bool {
    let entry_repr = entry.codegen_repr();
    let exit_repr = exit.codegen_repr();
    if entry_repr == exit_repr {
        return false;
    }
    matches!(entry, PhpType::Never)
        || entry_repr == PhpType::Void
        || exit_repr == PhpType::Mixed
}"""
assert s.count(old)==1
s=s.replace(old,new)
s=s.replace('            eprintln!("DEBUG byref exit {pname} entry={entry_ty:?} exit={exit_ty:?}");\n','')
s=s.replace('                eprintln!("DEBUG after re-resolve {name} -> {:?}", self.functions.get(name).map(|s| s.params.clone()));\n','')
open(p,'w').write(s)

p2='src/ir_lower/expr/call_arg_coercion.rs'
s2=open(p2).read()
s2=s2.replace('    eprintln!("DEBUG conv name={name} param={:?} local={local_ty:?}", param_ty.codegen_repr());\n','')
# the same Never-vs-Void trap applies to the call-site gate
s2=s2.replace("            if local_elem == PhpType::Never && param_elem != PhpType::Never {",
              "            if local_elem == PhpType::Void && param_elem != PhpType::Void {")
s2=s2.replace("            if local_value == PhpType::Never && param_value != PhpType::Never {",
              "            if local_value == PhpType::Void && param_value != PhpType::Void {")
open(p2,'w').write(s2)
print('Never/Void repr trap fixed, debug removed')
